// Claude's review tests for A42 (the sample project). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { exportProject, parseProjectFile } from './exportFile';
import { findMock } from './match';
import { SAMPLE_TIP, sampleProject } from './sample';
import { mergeProject } from './scenarioOps';
import { newProject, type Mock } from './types';

const all = (): Mock[] => sampleProject().scenarios.flatMap((s) => s.mocks);

describe('sampleProject', () => {
  it('has the three scenarios, Default first', () => {
    expect(sampleProject().scenarios.map((s) => s.name)).toEqual(['Default', 'Checkout down', 'Slow network']);
  });

  it('shows every reply type, a template, conditions and a SignalR hub', () => {
    const kinds = new Set(all().map((m) => m.reply ?? 'fixed'));
    for (const k of ['fixed', 'code', 'sequence', 'patch', 'stream']) expect(kinds.has(k as never)).toBe(true);
    expect(all().some((m) => m.templates === true)).toBe(true);
    expect(all().some((m) => m.match !== undefined && Object.keys(m.match).length > 0)).toBe(true);
    const sockets = sampleProject().scenarios.flatMap((s) => s.sockets ?? []);
    expect(sockets.some((s) => s.kind === 'signalr' && s.enabled && (s.onConnect.length > 0 || s.replies.length > 0))).toBe(true);
  });

  it('every mock is enabled and every id is unique', () => {
    const p = sampleProject();
    expect(all().every((m) => m.enabled)).toBe(true);
    const ids = [
      ...p.scenarios.map((s) => s.id),
      ...all().map((m) => m.id),
      ...p.scenarios.flatMap((s) => s.sockets ?? []).flatMap((s) => [s.id, ...s.onConnect.map((x) => x.id), ...s.replies.map((r) => r.id)]),
    ];
    expect(new Set(ids).size).toBe(ids.length);
  });

  it('is a valid wemock file (export, then import, gives it back)', () => {
    const r = parseProjectFile(exportProject(sampleProject()));
    expect(r.ok).toBe(true);
    if (r.ok) expect(r.project.scenarios.map((s) => s.mocks.length)).toEqual(sampleProject().scenarios.map((s) => s.mocks.length));
  });

  it('the tip names a call that a Default mock answers', () => {
    expect(SAMPLE_TIP).toBe('Try it in the Test bar: GET /api/products/42');
    const hit = findMock(sampleProject().scenarios[0]!.mocks, { method: 'GET', url: 'http://localhost:5173/api/products/42' });
    expect(hit).not.toBeNull();
  });

  it('a fresh copy each call: changing one never changes the next', () => {
    const a = sampleProject();
    a.scenarios[0]!.mocks[0]!.urlPattern = '/changed';
    expect(sampleProject().scenarios[0]!.mocks[0]!.urlPattern).not.toBe('/changed');
  });

  it('adding it keeps what the site already has', () => {
    const mine = newProject('p1', 'http://localhost:5173');
    mine.scenarios[0]!.mocks.push({ ...all()[0]!, id: 'mine', urlPattern: '/mine' });
    let n = 0;
    const merged = mergeProject(mine, sampleProject(), () => `n${++n}`);
    expect(merged.scenarios[0]!.mocks[0]!.id).toBe('mine');
    expect(merged.scenarios.map((s) => s.name)).toEqual(['Default', 'Checkout down', 'Slow network']);
    expect(merged.id).toBe('p1');
  });
});
